define.example:
const { Animations } = kcds.characters;
const { Events } = kcds.core;

Animations.define('whip_strike', {
  keys: [
    { time: 0, pose: { RightArm: [40, 0, 0] } },
    { time: 0.4, pose: { RightArm: [130, 0, -40], RightForeArm: [0, 0, 70] } },
    { time: 1.2, pose: { RightArm: [40, 0, 0] } },
  ],
  loop: false,
});

Events.on('playerReady', (player) => {
  player.playAnimation('whip_strike');
});

define.exampleCs:
Animations.Define("whip_strike", new { keys = new object[] { new { time = 0, pose = new Dictionary<string, object?> { ["RightArm"] = new[] { 40, 0, 0 } } }, new { time = 0.4, pose = new Dictionary<string, object?> { ["RightArm"] = new[] { 130, 0, -40 }, ["RightForeArm"] = new[] { 0, 0, 70 } } }, new { time = 1.2, pose = new Dictionary<string, object?> { ["RightArm"] = new[] { 40, 0, 0 } } } }, loop = false });

Events.On("playerReady", (Player player) =>
{
    player.PlayAnimation("whip_strike");
});

